public sealed partial class WorkspaceWindow
{
    async Task RevisionProbe(string fixture,string directory){Directory.CreateDirectory(directory);try{var reader=await OpenDocument(fixture)??throw new IOException("Fixture did not open.");await reader.RevisionChecks(directory);CaptureWorkspace(Path.Combine(directory,"page-tags.png"));await reader.ShowStickyExpandedProbe();CaptureWorkspace(Path.Combine(directory,"expanded-tag.png"));await reader.ShowRadialProbe();CaptureWorkspace(Path.Combine(directory,"two-action-wheel.png"));reader.HideRadialProbe();if(startupArgs.Length>=4){var legacy=await OpenDocument(startupArgs[3])??throw new IOException("Previous tagged copy did not open.");var checks=await legacy.CompatibilityTagChecks();File.WriteAllText(Path.Combine(directory,"tag-compatibility.json"),JsonSerializer.Serialize(new{Passed=checks.Values.All(v=>v),Checks=checks},new JsonSerializerOptions{WriteIndented=true}));}}catch(Exception ex){File.WriteAllText(Path.Combine(directory,"revision-probe.json"),JsonSerializer.Serialize(new{Error=ex.ToString()}));}finally{closingApproved=true;Close();}}
}
