    internal async Task ShowStickyExpandedProbe(){await SetFit(false);await ShowPage(2);expandedTag=pageTags[0].Id;PositionStickyTags();await RenderCycle();}
    internal async Task<Dictionary<string,bool>> CompatibilityTagChecks(){var checks=new Dictionary<string,bool>();var original=Program.HashFile(currentFile);await bookmarkAppearanceTask;var stored=await PdfOutlineStore.ReadMetadataAsync(currentFile,CancellationToken.None);checks["PreviousVersionTagsReadWithIdenticalTitlesColorsPagesAndOffsets"]=stored.Tags.Count>0&&stored.Tags.SequenceEqual(pageTags);await ShowPage(Math.Min(2,engine.PageCount-1));await RenderCycle();checks["PreviousVersionTagsRemainVisibleAcrossPages"]=stickyButtons.Count==stored.Tags.Count&&stickyButtons.Values.All(b=>b.IsVisible);var target=pageTags.First(t=>t.Page!=currentPage);UiInputProbe.Click(this,stickyButtons[target.Id]);await ProbeWait(()=>currentPage==target.Page&&displayedPage==target.Page&&loadingBadge.Visibility!=Visibility.Visible);checks["PreviousVersionTagCanJumpAcrossPages"]=currentPage==target.Page;checks["PreviousTaggedCopyUnchanged"]=original.SequenceEqual(Program.HashFile(currentFile));return checks;}
